import{_ as e,o as r,c as o,a3 as d}from"./chunks/framework.BCm1YVWY.js";const u=JSON.parse('{"title":"Monad Agent Kit — Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"ROADMAP.md","filePath":"ROADMAP.md"}'),a={name:"ROADMAP.md"};function i(n,t,s,l,c,g){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="monad-agent-kit-—-roadmap" tabindex="-1">Monad Agent Kit — Roadmap <a class="header-anchor" href="#monad-agent-kit-—-roadmap" aria-label="Permalink to &quot;Monad Agent Kit — Roadmap&quot;">​</a></h1><p>Progress tracker, competitive positioning, and feature backlog.</p><hr><h2 id="competitive-landscape" tabindex="-1">Competitive Landscape <a class="header-anchor" href="#competitive-landscape" aria-label="Permalink to &quot;Competitive Landscape&quot;">​</a></h2><h3 id="the-big-three" tabindex="-1">The Big Three <a class="header-anchor" href="#the-big-three" aria-label="Permalink to &quot;The Big Three&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kit</th><th>Chain</th><th>Actions</th><th>AI Frameworks</th><th>Wallets</th><th>Language</th></tr></thead><tbody><tr><td><strong>Solana Agent Kit</strong></td><td>Solana</td><td>60+</td><td>LangChain, Vercel AI, OpenAI</td><td>Keypair</td><td>TypeScript</td></tr><tr><td><strong>Coinbase AgentKit</strong></td><td>All EVM + Solana</td><td>50+ (TS), 30+ (Python)</td><td>LangChain, Vercel AI, MCP, OpenAI Agents SDK, Pydantic AI</td><td>CDP, Privy, Viem</td><td>TypeScript, Python</td></tr><tr><td><strong>GOAT SDK</strong></td><td>15+ chains</td><td>200+</td><td>Vercel AI, LangChain, LlamaIndex, OpenAI Agents SDK, CrewAI, Eliza, MCP</td><td>Crossmint, Lit, Safe, 12+ providers</td><td>TypeScript, Python</td></tr><tr><td><strong>Monad Agent Kit</strong></td><td>Monad</td><td>~25</td><td>Vercel AI, LangChain, MCP</td><td>Private key (viem)</td><td>TypeScript</td></tr></tbody></table><h3 id="what-each-kit-does-well" tabindex="-1">What Each Kit Does Well <a class="header-anchor" href="#what-each-kit-does-well" aria-label="Permalink to &quot;What Each Kit Does Well&quot;">​</a></h3><p><strong>Solana Agent Kit</strong> — Deep protocol coverage</p><ul><li>NFT minting, listing, metadata via Metaplex</li><li>Compressed airdrops (ZK proofs via Light Protocol)</li><li>Perpetual trading (Drift, Adrena)</li><li>Limit orders (Manifest)</li><li>Cross-chain bridging (Wormhole, deBridge)</li><li>Token launches (Pump.fun)</li><li>Domain registration (SNS, Alldomains)</li><li>Price feeds (Pyth, CoinGecko)</li></ul><p><strong>Coinbase AgentKit</strong> — Safety and wallet infrastructure</p><ul><li>Multiple wallet providers (CDP Smart Wallet, Privy, Viem)</li><li>Smart wallet support (account abstraction)</li><li>Fiat onramp built-in</li><li>Action provider scoping, least-privilege security model</li><li>Human approval gates for high-risk operations</li><li>Quickstart CLI (<code>npm create onchain-agent@latest</code>)</li><li>Both TypeScript and Python SDKs</li></ul><p><strong>GOAT SDK</strong> — Breadth and framework coverage</p><ul><li>200+ plugins across every major protocol</li><li>15+ chains, 12+ wallet providers</li><li>10+ AI framework adapters (including Eliza, CrewAI, GAME)</li><li>Prediction markets (Polymarket)</li><li>Modular &quot;install only what you need&quot; architecture</li></ul><hr><h2 id="feature-comparison-ours-vs-theirs" tabindex="-1">Feature Comparison: Ours vs Theirs <a class="header-anchor" href="#feature-comparison-ours-vs-theirs" aria-label="Permalink to &quot;Feature Comparison: Ours vs Theirs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Solana</th><th>Coinbase</th><th>GOAT</th><th><strong>Monad (Ours)</strong></th></tr></thead><tbody><tr><td><strong>Token transfers</strong></td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>Token balances</strong></td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td><strong>DEX swaps</strong></td><td>✅ Jupiter</td><td>✅</td><td>✅ Uniswap, Jupiter</td><td>✅ Kuru, 0x</td></tr><tr><td><strong>Staking</strong></td><td>✅ JupSOL, Solayer</td><td>✅</td><td>✅</td><td>✅ aPriori</td></tr><tr><td><strong>Liquidity provision</strong></td><td>✅ Raydium, Orca, Meteora</td><td>❌</td><td>✅</td><td>✅ Kuru</td></tr><tr><td><strong>NFTs</strong></td><td>✅ Metaplex, 3.Land</td><td>✅ OpenSea</td><td>✅ Magic Eden, OpenSea</td><td>✅ ERC-721</td></tr><tr><td><strong>Portfolio tracking</strong></td><td>❌</td><td>❌</td><td>❌</td><td>✅ <strong>Unique</strong></td></tr><tr><td><strong>Batch transfers</strong></td><td>❌</td><td>❌</td><td>❌</td><td>✅ <strong>Unique</strong></td></tr><tr><td><strong>Multi-swap</strong></td><td>❌</td><td>❌</td><td>❌</td><td>✅ <strong>Unique</strong></td></tr><tr><td><strong>Safety rails</strong></td><td>❌</td><td>✅ Action scoping, approval gates</td><td>❌</td><td>✅ Action scoping, spending limits, approval gates</td></tr><tr><td><strong>Lending/Borrowing</strong></td><td>✅ Drift, Lulo</td><td>✅ Compound, Morpho, Moonwell</td><td>✅</td><td>❌</td></tr><tr><td><strong>Perpetuals</strong></td><td>✅ Drift, Adrena</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td><strong>Bridging</strong></td><td>✅ Wormhole, deBridge</td><td>❌</td><td>✅ deBridge</td><td>❌</td></tr><tr><td><strong>Price feeds</strong></td><td>✅ Pyth, CoinGecko</td><td>✅ DefiLlama</td><td>✅ CoinGecko, Dexscreener</td><td>✅ DEX quotes</td></tr><tr><td><strong>Domain names</strong></td><td>✅ SNS, Alldomains</td><td>❌</td><td>❌</td><td>❌</td></tr><tr><td><strong>Prediction markets</strong></td><td>❌</td><td>❌</td><td>✅ Polymarket</td><td>❌</td></tr><tr><td><strong>Smart contract deploy</strong></td><td>❌</td><td>✅</td><td>❌</td><td>❌</td></tr><tr><td><strong>Generic contract calls</strong></td><td>❌</td><td>❌</td><td>❌</td><td>✅ <code>readContract</code>/<code>writeContract</code></td></tr><tr><td><strong>Tx simulation</strong></td><td>❌</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td><strong>Multiple wallet providers</strong></td><td>❌</td><td>✅ CDP, Privy, Viem</td><td>✅ 12+ providers</td><td>✅ EIP-1193</td></tr><tr><td><strong>Quickstart CLI</strong></td><td>❌</td><td>✅</td><td>❌</td><td>✅ <code>bun create monad-agent</code></td></tr><tr><td><strong>Python SDK</strong></td><td>❌</td><td>✅</td><td>✅</td><td>❌</td></tr><tr><td><strong>Fiat onramp</strong></td><td>❌</td><td>✅</td><td>❌</td><td>❌</td></tr></tbody></table><hr><h2 id="our-unique-strengths" tabindex="-1">Our Unique Strengths <a class="header-anchor" href="#our-unique-strengths" aria-label="Permalink to &quot;Our Unique Strengths&quot;">​</a></h2><ul><li><strong>Portfolio tracking with USD values</strong> — No other kit has this built-in</li><li><strong>Batch transfers</strong> (mixed native + ERC-20) — Unique feature</li><li><strong>Multi-swap</strong> (split, consolidate, batch) — Unique feature</li><li><strong>Token price via on-chain DEX quotes</strong> — More decentralized than CoinGecko API dependency</li><li><strong>Monad-first</strong> — Deep integration with Monad protocols (Kuru, aPriori) that no other kit covers</li></ul><hr><h2 id="feature-roadmap" tabindex="-1">Feature Roadmap <a class="header-anchor" href="#feature-roadmap" aria-label="Permalink to &quot;Feature Roadmap&quot;">​</a></h2><h3 id="core-tokens" tabindex="-1">Core &amp; Tokens <a class="header-anchor" href="#core-tokens" aria-label="Permalink to &quot;Core &amp; Tokens&quot;">​</a></h3><ul><li>[x] <strong>Token transfers, balances, approve, allowance</strong> — plugin-token</li><li>[x] <strong>Token info &amp; pricing</strong> — <code>getTokenInfo</code>, <code>getTokenPrice</code> in plugin-tokens</li><li>[x] <strong>Transaction history</strong> — <code>getTransactionHistory</code> in plugin-tokens</li><li>[x] <strong>Token discovery / portfolio</strong> — <code>getPortfolio</code> via Multicall3 in plugin-tokens</li><li>[x] <strong>First activity detection</strong> — <code>getFirstActivity</code> in plugin-tokens</li><li>[x] <strong>NFT support</strong> — <code>getNFTs</code>, <code>transferNFT</code>, <code>getNFTMetadata</code> (ERC-721) in plugin-nft</li></ul><h3 id="defi" tabindex="-1">DeFi <a class="header-anchor" href="#defi" aria-label="Permalink to &quot;DeFi&quot;">​</a></h3><ul><li>[x] <strong>DEX swaps</strong> — Kuru DEX (<code>getQuote</code>, <code>swap</code>)</li><li>[x] <strong>DEX aggregation</strong> — 0x (<code>getQuote0x</code>, <code>swap0x</code>, <code>getBestQuote</code>)</li><li>[x] <strong>Staking</strong> — aPriori (<code>stake</code>, <code>requestUnstake</code>, <code>claimUnstake</code>, <code>getStakeInfo</code>)</li><li>[x] <strong>Liquidity provision</strong> — Kuru (<code>addLiquidity</code>, <code>removeLiquidity</code>, <code>getPoolInfo</code>)</li><li>[x] <strong>Wrap/Unwrap</strong> — <code>wrapMON</code>, <code>unwrapWMON</code></li><li>[x] <strong>LP position tracker</strong> — Query user&#39;s LP positions on Kuru pools (<code>getLPPositions</code>)</li><li>[x] <strong>Limit orders</strong> — Place, cancel, and query limit orders on Kuru (<code>placeLimitOrder</code>, <code>cancelLimitOrder</code>, <code>getLimitOrders</code>)</li><li>[ ] <strong>Lending protocols</strong> — Deposit, borrow, repay (when Monad lending protocols launch)</li><li>[ ] <strong>Yield farming</strong> — Auto-compound, farm positions</li></ul><h3 id="gas-transactions" tabindex="-1">Gas &amp; Transactions <a class="header-anchor" href="#gas-transactions" aria-label="Permalink to &quot;Gas &amp; Transactions&quot;">​</a></h3><ul><li>[x] <strong>Batch transactions</strong> — <code>batchTransfer</code> in plugin-token, <code>multiSwap</code> in plugin-defi</li><li>[x] <strong>Gas estimation</strong> — <code>estimateGas</code> action in plugin-tokens: gas units, gas price, cost in MON</li><li>[x] <strong>Tx simulation</strong> — <code>eth_call</code> to dry-run, show balance changes &amp; potential errors</li></ul><h3 id="safety-infrastructure" tabindex="-1">Safety &amp; Infrastructure <a class="header-anchor" href="#safety-infrastructure" aria-label="Permalink to &quot;Safety &amp; Infrastructure&quot;">​</a></h3><ul><li>[x] <strong>Safety rails</strong> — SafetyPolicy in core: action scoping, spending limits (per-action &amp; daily), human approval gates</li><li>[x] <strong>Address whitelist</strong> — Only interact with approved addresses, integrated in SafetyPolicy</li><li>[x] <strong>Multiple wallet providers</strong> — EIP-1193 adapter for any browser/injected provider</li><li>[ ] <strong>Multi-sig support</strong> — Safe/multi-sig wallet integration</li></ul><h3 id="agent-intelligence" tabindex="-1">Agent Intelligence <a class="header-anchor" href="#agent-intelligence" aria-label="Permalink to &quot;Agent Intelligence&quot;">​</a></h3><ul><li>[ ] <strong>Price alerts</strong> — Notify when token hits target price</li><li>[ ] <strong>Auto-rebalance</strong> — Keep portfolio at target allocations</li><li>[ ] <strong>DCA bot</strong> — Dollar-cost averaging into tokens</li><li>[ ] <strong>Copy trading</strong> — Mirror another wallet&#39;s trades</li></ul><h3 id="analytics" tabindex="-1">Analytics <a class="header-anchor" href="#analytics" aria-label="Permalink to &quot;Analytics&quot;">​</a></h3><ul><li>[ ] <strong>PnL tracking</strong> — Calculate profit/loss on positions</li><li>[ ] <strong>Portfolio analytics</strong> — Charts, allocation breakdown</li><li>[ ] <strong>Whale watching</strong> — Track large wallets</li></ul><h3 id="developer-experience" tabindex="-1">Developer Experience <a class="header-anchor" href="#developer-experience" aria-label="Permalink to &quot;Developer Experience&quot;">​</a></h3><ul><li>[x] <strong>Quickstart CLI</strong> — <code>npm create monad-agent</code> scaffolding</li><li>[x] <strong>Generic contract interaction</strong> — User-facing <code>readContract</code>/<code>writeContract</code> actions</li><li>[x] <strong>ENS / name resolution</strong> — Extensible resolver interface (<code>NameResolver</code>, <code>resolveNameOrAddress</code>)</li></ul><h3 id="long-term" tabindex="-1">Long-term <a class="header-anchor" href="#long-term" aria-label="Permalink to &quot;Long-term&quot;">​</a></h3><ul><li>[ ] <strong>Cross-chain bridging</strong> — When bridges are live on Monad</li><li>[ ] <strong>Python SDK</strong> — Coinbase and GOAT both have it</li><li>[ ] <strong>Action composability</strong> — Workflows chaining multiple actions</li><li>[x] <strong>Agent memory / tx log</strong> — Persistent action history</li><li>[x] <strong>Event monitoring</strong> — Subscribe to on-chain events (<code>subscribeEvents</code>, <code>getEventLog</code>, <code>unsubscribeEvents</code>)</li></ul><hr><h2 id="implementation-priority" tabindex="-1">Implementation Priority <a class="header-anchor" href="#implementation-priority" aria-label="Permalink to &quot;Implementation Priority&quot;">​</a></h2><h3 id="tier-1-essential-gaps-competitors-have-it-we-don-t" tabindex="-1">Tier 1: Essential gaps (competitors have it, we don&#39;t) <a class="header-anchor" href="#tier-1-essential-gaps-competitors-have-it-we-don-t" aria-label="Permalink to &quot;Tier 1: Essential gaps (competitors have it, we don&#39;t)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Feature</th><th>Effort</th><th>Status</th></tr></thead><tbody><tr><td><s>1</s></td><td><s>Safety rails</s></td><td><s>Medium</s></td><td>✅ Done</td></tr><tr><td><s>2</s></td><td><s>NFT support (ERC-721)</s></td><td><s>Easy</s></td><td>✅ Done</td></tr><tr><td><s>3</s></td><td><s>Tx simulation</s></td><td><s>Easy</s></td><td>✅ Done</td></tr><tr><td><s>4</s></td><td><s>Gas estimation</s></td><td><s>Easy</s></td><td>✅ Done</td></tr></tbody></table><h3 id="tier-2-competitive-edge-differentiation-opportunities" tabindex="-1">Tier 2: Competitive edge (differentiation opportunities) <a class="header-anchor" href="#tier-2-competitive-edge-differentiation-opportunities" aria-label="Permalink to &quot;Tier 2: Competitive edge (differentiation opportunities)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Feature</th><th>Effort</th><th>Status</th></tr></thead><tbody><tr><td><s>5</s></td><td><s>Generic contract interaction</s></td><td><s>Medium</s></td><td>✅ Done</td></tr><tr><td><s>6</s></td><td><s>Quickstart CLI</s></td><td><s>Medium</s></td><td>✅ Done</td></tr><tr><td><s>7</s></td><td><s>Multiple wallet providers</s></td><td><s>Medium</s></td><td>✅ Done</td></tr></tbody></table><h3 id="tier-3-future-nice-to-have-not-blocking" tabindex="-1">Tier 3: Future (nice to have, not blocking) <a class="header-anchor" href="#tier-3-future-nice-to-have-not-blocking" aria-label="Permalink to &quot;Tier 3: Future (nice to have, not blocking)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Feature</th><th>Effort</th><th>Status</th></tr></thead><tbody><tr><td>8</td><td>Lending protocols</td><td>Medium</td><td>Pending</td></tr><tr><td>9</td><td>Cross-chain bridging</td><td>Medium</td><td>Pending</td></tr><tr><td>10</td><td>LP position tracker</td><td>Medium</td><td>Done</td></tr><tr><td>11</td><td>Python SDK</td><td>High</td><td>Pending</td></tr><tr><td>12</td><td>Action composability</td><td>High</td><td>Pending</td></tr><tr><td>13</td><td>Event monitoring</td><td>High</td><td>Done</td></tr></tbody></table><hr><h2 id="progress-summary" tabindex="-1">Progress Summary <a class="header-anchor" href="#progress-summary" aria-label="Permalink to &quot;Progress Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Done</th><th>Total</th><th>%</th></tr></thead><tbody><tr><td>Core &amp; Tokens</td><td>7</td><td>7</td><td>100%</td></tr><tr><td>DeFi</td><td>5</td><td>9</td><td>56%</td></tr><tr><td>Gas &amp; Transactions</td><td>3</td><td>3</td><td>100%</td></tr><tr><td>Safety &amp; Infrastructure</td><td>3</td><td>4</td><td>75%</td></tr><tr><td>Agent Intelligence</td><td>0</td><td>4</td><td>0%</td></tr><tr><td>Analytics</td><td>0</td><td>3</td><td>0%</td></tr><tr><td>Developer Experience</td><td>3</td><td>3</td><td>100%</td></tr><tr><td>Long-term</td><td>1</td><td>5</td><td>20%</td></tr><tr><td><strong>Total</strong></td><td><strong>21</strong></td><td><strong>38</strong></td><td><strong>55%</strong></td></tr></tbody></table><hr><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><ul><li><a href="https://github.com/sendaifun/solana-agent-kit" target="_blank" rel="noreferrer">Solana Agent Kit — GitHub</a></li><li><a href="https://github.com/coinbase/agentkit" target="_blank" rel="noreferrer">Coinbase AgentKit — GitHub</a></li><li><a href="https://docs.cdp.coinbase.com/agent-kit/welcome" target="_blank" rel="noreferrer">Coinbase AgentKit — Docs</a></li><li><a href="https://github.com/goat-sdk/goat" target="_blank" rel="noreferrer">GOAT SDK — GitHub</a></li><li><a href="https://blog.crossmint.com/introducing-goat-great-onchain-agent-toolkit/" target="_blank" rel="noreferrer">GOAT Introduction — Crossmint Blog</a></li><li><a href="https://www.coinbase.com/developer-platform/discover/launches/agentkit-q1-update" target="_blank" rel="noreferrer">AgentKit Q1 Update — Coinbase</a></li></ul>',51)])])}const p=e(a,[["render",i]]);export{u as __pageData,p as default};
